package com.seamless.player;

import android.app.*;import android.os.*;import android.Manifest;import android.content.*;import android.content.pm.PackageManager;import android.database.Cursor;import android.graphics.Color;import android.net.Uri;import android.provider.MediaStore;import android.view.*;import android.widget.*;import android.media.MediaPlayer;import java.util.*;

public class MainActivity extends Activity {
 static MediaPlayer player; static ArrayList<Track> tracks=new ArrayList<>(); static int index=-1; TextView title,status; SeekBar seek; LinearLayout root; Handler handler=new Handler(); int accent=0xFFB7A58A;
 static class Track { Uri uri; String name,artist; Track(Uri u,String n,String a){uri=u;name=n;artist=a;} }
 @Override public void onCreate(Bundle b){super.onCreate(b);getWindow().setStatusBarColor(Color.BLACK);getWindow().setNavigationBarColor(Color.BLACK); if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(Manifest.permission.READ_MEDIA_AUDIO)!=PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{Manifest.permission.READ_MEDIA_AUDIO},9); build(); load(); handler.post(tick);}
 void build(){root=new LinearLayout(this);root.setOrientation(1);root.setPadding(22,26,22,18);root.setBackgroundColor(Color.BLACK);setContentView(root);
 TextView brand=text("seamless",30,Color.WHITE);root.addView(brand);TextView sub=text("YOUR MUSIC. YOUR SPACE.",10,0xFF999999);root.addView(sub);
 title=text("Choose a track",22,Color.WHITE);LinearLayout.LayoutParams tp=new LinearLayout.LayoutParams(-1,-2);tp.topMargin=34;root.addView(title,tp);
 status=text("AMOLED · LOCAL MUSIC",12,0xFFAAAAAA);root.addView(status);
 seek=new SeekBar(this);seek.setMax(1000);root.addView(seek);seek.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onProgressChanged(SeekBar s,int p,boolean u){if(u&&player!=null)player.seekTo((int)(player.getDuration()*p/1000f));}public void onStartTrackingTouch(SeekBar s){}public void onStopTrackingTouch(SeekBar s){}});
 LinearLayout controls=new LinearLayout(this);controls.setGravity(Gravity.CENTER);root.addView(controls);addButton(controls,"PREV",()->play(index-1));addButton(controls,"PLAY / PAUSE",()->toggle());addButton(controls,"NEXT",()->play(index+1));
 TextView section=text("YOUR LIBRARY",12,accent);LinearLayout.LayoutParams sp=new LinearLayout.LayoutParams(-1,-2);sp.topMargin=28;root.addView(section,sp);
 ScrollView scroll=new ScrollView(this);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1)); LinearLayout list=new LinearLayout(this);list.setOrientation(1);scroll.addView(list); list.setTag("list");
 Button theme=new Button(this);theme.setText("CUSTOMIZE APPEARANCE");theme.setTextColor(accent);theme.setBackgroundColor(0xFF171717);root.addView(theme);theme.setOnClickListener(v->themeDialog()); }
 TextView text(String s,int size,int color){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(color);return t;}
 void addButton(LinearLayout l,String s,Runnable r){Button b=new Button(this);b.setText(s);b.setTextSize(10);b.setTextColor(accent);l.addView(b);b.setOnClickListener(v->r.run());}
 void load(){if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(Manifest.permission.READ_MEDIA_AUDIO)!=PackageManager.PERMISSION_GRANTED)return;tracks.clear();String[] p={MediaStore.Audio.Media._ID,MediaStore.Audio.Media.TITLE,MediaStore.Audio.Media.ARTIST};try(Cursor c=getContentResolver().query(MediaStore.Audio.Media.EXTERNAL_CONTENT_URI,p,MediaStore.Audio.Media.IS_MUSIC+"!=0",null,MediaStore.Audio.Media.TITLE+" ASC")){if(c!=null)while(c.moveToNext()){tracks.add(new Track(Uri.withAppendedPath(MediaStore.Audio.Media.EXTERNAL_CONTENT_URI,c.getString(0)),c.getString(1),c.getString(2)));}} LinearLayout list=(LinearLayout)((ScrollView)root.getChildAt(7)).getChildAt(0);list.removeAllViews(); if(tracks.isEmpty()){list.addView(text("No local music found yet. Add audio files to your phone, then reopen Seamless.",14,0xFFAAAAAA));return;} for(int i=0;i<tracks.size();i++){final int n=i;TextView row=text("♫   "+tracks.get(i).name+"\n      "+tracks.get(i).artist,16,Color.WHITE);row.setPadding(8,15,8,15);list.addView(row);row.setOnClickListener(v->play(n));}}
 void play(int n){if(n<0||n>=tracks.size())return;try{if(player!=null){player.release();}index=n;player=new MediaPlayer();player.setDataSource(this,tracks.get(n).uri);player.setOnPreparedListener(mp->{mp.start();title.setText(tracks.get(index).name);status.setText("NOW PLAYING · LOCAL AUDIO");});player.setOnCompletionListener(mp->play(index+1));player.prepareAsync();}catch(Exception e){status.setText("Unable to play this audio file");}sendBroadcast(new Intent("com.seamless.player.REFRESH"));}
 void toggle(){if(player==null){if(!tracks.isEmpty())play(0);return;}if(player.isPlaying())player.pause();else player.start();sendBroadcast(new Intent("com.seamless.player.REFRESH"));}
 void themeDialog(){String[] names={"Warm stone","Soft sage","Lavender","Ice blue","Amber"};int[] colors={0xFFB7A58A,0xFF9CAF9A,0xFFB5A5CC,0xFF91B7C7,0xFFD5A35B};new AlertDialog.Builder(this).setTitle("Accent color").setItems(names,(d,w)->{accent=colors[w];status.setText("THEME UPDATED · "+names[w].toUpperCase());}).setNegativeButton("Close",null).show();}
 Runnable tick=new Runnable(){public void run(){if(player!=null&&player.isPlaying()&&player.getDuration()>0)seek.setProgress((int)(1000f*player.getCurrentPosition()/player.getDuration()));handler.postDelayed(this,250);}};
 @Override public void onRequestPermissionsResult(int r,String[] p,int[] g){super.onRequestPermissionsResult(r,p,g);if(r==9&&g.length>0&&g[0]==0)load();}
}
